def round_half_to_even(n):
    """
    Round the input value to the nearest even integer.

    :param n: The number to round.
    :return: The rounded number.
    """
    if n % 1 == 0.5:
        return int(n) + 1 if int(n) % 2 == 1 else int(n)
    return round(n)

