def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    m = re.match(r"v?(\d+)\.(\d+)\.(\d+)(-(alpha|beta))?", s)
    if not m:
        raise ValueError(f"Invalid version string: {s}")
    major, minor, patch = [int(v) for v in m.groups()[:3]]
    release = m.group(4) or "final"
    return (major, minor, patch, release)

def normalize_cmd(cmd):
    if platform.system() == "Windows":
        cmd = cmd[0].lower()
        # Check if the command has a shebang or not
        if not cmd.startswith("#!"):
            # If not, assume it's a windows command and add the .exe extension
            return (cmd + ".exe",) + cmd[1:]
        else:
            # If it does, assume it's a unix command and remove the shebang
            return cmd[2:] + ".exe"
    else:
        return cmd

