def extostr(cls, e, max_level=30, max_path_level=5):
    stack = []
    current = e
    while current is not None and len(stack) < max_level:
        stack.append(current)
        current = current.__cause__
    stack.reverse()

    output = []
    for i, entry in enumerate(stack):
        if entry.__cause__ is None:
            exc_type, exc_value, exc_traceback = sys.exc_info()
            last = exc_traceback.tb_frame.f_back.f_code.co_name + "()"
        else:
            last = "<Unknown>"
        output.append(f"{i+1}: {type(entry).__name__}{': ' + str(entry) if str(entry) != '' else ''}; LastTraceback={last}")
    return '\n'.join(output)

def append_text_to_file(file_name, text_buffer, encoding, overwrite=False):
    assert isinstance(file_name, str), "The file name must be a string"
    assert isinstance(text_buffer, str), "The text buffer must be a string"
    assert isinstance(encoding, str), "The encoding must be a string"
    assert isinstance(overwrite, bool), "The overwrite parameter must be a boolean"

    if overwrite and os.path.exists(file_name):
        os.remove(file_name)

    with open(file_name, "ab") as f:
        f.write(text_buffer.encode(encoding))

    return len(text_buffer)

def is_file_exist(file_name):
    """
    Check if file name exist.
    :param file_name: File name.
    :type file_name: str
    :return: Return true (exist), false (do not exist, or invalid file name)
    :rtype bool
    """
    if not file_name:
        return False

    try:
        path = os.path.realpath(file_name)
        if os.path.isfile(path):
            return True
        else:
            return False
    except Exception:
        return False

