            min_bases.append(cls)
            seen.add(cls)
    return min_bases

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    bases = []
    for cls in classes:
        if cls not in bases:
            bases.append(cls)
            for b in cls.__bases__:
                if b not in bases:
                    bases.append(b)
    return tuple(bases)

def minimalBases(classes: Sequence[Type]) -> Sequence[Type]:
    seen: Set[Type] = set()
    minimal: List[Type] = []
    for cls in classes:
        if cls in seen:
            continue
        seen.add(cls)
        minimal.append(cls)
        for base in cls.__bases__:
            if base not in seen:
                seen.add(base)
                minimal.append(base)
    return minimal

