def fill(coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if not (-self._edges[0] <= coord[0] < self._edges[0]:
        return
    if not (-self._edges[1] <= coord[1] < self._edges[1]:
        return
    if not (-self._edges[2] <= coord[2] < self._edges[2]:
        return
    index = (int((coord[0] + self._edges[0]) / self._bin_widths[0]),
             int((coord[1] + self._edges[1]) / self._bin_widths[1]),
             int((coord[2] + self._edges[2]) / self._bin_widths[2]))
    if not (0 <= index[0] < self._n_bins[0]:
        return
    if not (0 <= index[1] < self._n_bins[1]:
        return
    if not (0 <= index[2] < self._n_bins[2]:
        return
    self._counts[index[0], index[1], index[2]] += weight

