def _validate_labels(labels):
    """
    Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    error_messages = []
    for key, value in labels.items():
        try:
            if not isinstance(key, (str, bytes)):
                raise ValidationError("expected string or bytes-like object")
            if not isinstance(value, (str, bytes)):
                raise ValidationError("expected string or bytes-like object")
        except:
            error_messages.append({"key": key, "value": "expected string or bytes-like object"})

    for key, value in labels.items():
        if key.startswith("$$"):
            error_messages.append({"key": key, "value": "Label key '$$' does not match the regex [...]"})
        if isinstance(value, list):
            for item in value:
                try:
                    if not isinstance(item, (str, bytes)):
                        raise ValidationError("expected string or bytes-like object")
                except:
                    error_messages.append({"value": "expected string or bytes-like object"})

    if error_messages:
        raise ValidationError(message=error_messages)

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding regular expressions."""
    # Initialize an empty list to store the error messages
    messages = []

    # Iterate over the labels
    for label_key, label_value in labels.items():
        # First, check that the label key matches its regular expression
        try:
            _validate_label_key(label_key)
        except ValidationError as e:
            # If an error occurs, add it to the messages list and continue with the next label
            messages.append({"label_key": e.message})
            continue

        # Second, check that the label value matches its regular expression
        try:
            _validate_label_value(label_value)
        except ValidationError as e:
            # If an error occurs, add it to the messages list and continue with the next label
            messages.append({"label_value": e.message})
            continue

    # If there are any errors, raise a ValidationError with the messages list as the error message
    if messages:
        raise ValidationError(messages)

