def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    if not last_applied_manifest:
        return
    if not response:
        return
    if not observer_schema:
        return

    # Iterate over the response and update the corresponding fields in the last_applied_manifest
    for i, resp_field in enumerate(response):
        if i >= len(observer_schema):
            break
        field_name = observer_schema[i].get('name', None)
        if not field_name:
            continue
        if field_name not in last_applied_manifest:
            last_applied_manifest[field_name] = []
        update_last_applied_manifest_list_from_resp(last_applied_manifest[field_name], observer_schema[i]['observer_schema'], resp_field)

    # Iterate over the remaining fields in the last_applied_manifest and nullify them if they are not present in the response
    for field_name, field_value in last_applied_manifest.items():
        if field_name not in response:
            last_applied_manifest[field_name] = None

