def update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema, response):
    for field, field_type in observer_schema.items():
        if field not in response:
            raise KeyError(f"observed field '{field}' is not present in the Kubernetes response")
        field_value = response[field]
        if field_value is not None and field in last_applied_manifest:
            if field_type == dict:
                update_last_applied_manifest_dict_from_resp(last_applied_manifest[field], observer_schema[field], field_value)
            elif field_type == list:
                update_last_applied_manifest_list_from_resp(last_applied_manifest[field], observer_schema[field], field_value)
            else:
                last_applied_manifest[field] = field_value
        elif field_value is not None:
            last_applied_manifest[field] = field_value

def update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema, response):
    for observer in observer_schema.get("observers"):
        field = observer.get("field")
        current_manifest_value = last_applied_manifest.get(field)
        current_response_value = response.get(field)
        if current_response_value is not None:
            if current_manifest_value is None:
                last_applied_manifest[field] = current_response_value
            elif current_response_value != current_manifest_value:
                raise KeyError(f"Conflicting values '{current_response_value}' and '{current_manifest_value}' for observed field '{field}'")
        else:
            last_applied_manifest.pop(field)
    if "submanifests" in observer_schema:
        for submanifest in observer_schema.get("submanifests"):
            submanifest_last_applied = last_applied_manifest.get(submanifest) or {}
            submanifest_response = response.get(submanifest)
            if submanifest_response is not None:
                update_last_applied_manifest_dict_from_resp(submanifest_last_applied, submanifest, submanifest_response)
            else:
                if submanifest_last_applied:
                    last_applied_manifest.pop(submanifest)
                continue
        return last_applied_manifest

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    manifest = app.spec.manifest
    default_observer_schema = {}
    for resource in manifest.resources:
        resource_schema = {}
        for field in resource.manifest.flatten():
            if field.name not in ["apiVersion", "kind", "metadata"]:
                field_type = field.type
                field_usage = field.usage
                if field_type == "integer":
                    resource_schema[field.name] = {
                        "type": "integer",
                        "usage": field_usage,
                    }
                elif field_type == "array":
                    resource_schema[field.name] = {
                        "type": "array",
                        "usage": field_usage,
                        "sub": [],
                    }
                elif field_type == "string":
                    resource_schema[field.name] = {
                        "type": "string",
                        "usage": field_usage,
                    }
                elif field_type in ["switch", "boolean"]:
                    resource_schema[field.name] = {
                        "type": "boolean",
                        "usage": field_usage,
                    }
                elif field_type in ["fixed", "enumeration"]:
                    resource_schema[field.name] = {
                        "type": "enumeration",
                        "usage": field_usage,
                        "values": field.values,
                    }
        default_observer_schema[resource.available_name] = {
            "type": "schema",
            "usage": "resource",
            "sub": resource_schema,
        }
    return default_observer_schema

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    for resource in app.spec.manifest.resources:
        if resource.generate_observer_schema:
            continue
        if resource.startswith('CustomResourceDefinition'):
            continue
        if not hasattr(resource, 'status'):
            resource.status = {}
        observer_schema = Schema({
            'properties': {
                'status': {
                    'type': 'object',
                    'properties': {
                        # status is an object that contains the status of the resource
                        # it should have a type field and a about field
                        # if the type is about, the about field should contain a reference to the resource
                    }
                }
            }
        })
        resource.angular_element.schemas['default'] = observer_schema
    return app

def generate_default_observer_schema(app):
