    return default_observer_schema

def format(sql, params):
    if type(params) == dict:
        for key in params.keys():
            params[key] = ':' + key
        return (sql, params)
    elif type(params) == list:
        for idx, param in enumerate(params):
            params[idx] = ':' + str(idx)
        return (sql, params)
    else:
        raise TypeError('parameters must be a dictionary or a list of parameters')

def format(self, sql, params):
    # Check if params is a dictionary or sequence
    if isinstance(params, dict):
        # If params is a dictionary, get the dictionary values
        params_values = params.values()
    elif isinstance(params, (list, tuple)):
        # If params is a sequence, get the sequence elements
        params_values = params
    else:
        # If params is not a dictionary or sequence, raise an error
        raise ValueError("params must be a dictionary or a sequence")

    # Create a copy of the sql statement
    formatted_sql = sql

    # Iterate over the params values
    for param in params_values:
        # Replace instances of {0} with the param
        formatted_sql = formatted_sql.replace("{0}", param)

    # Return the formatted sql statement and the converted params
    return (formatted_sql, params_values)

def formatmany(self, sql, many_params):
    # Convert the SQL query to use the out-style parameters instead of the in-style parameters
    formatted_sql = sql
    out_style_args = []
    for params in many_params:
        if isinstance(params, Mapping):
            # Named parameter style
            formatted_sql = formatted_sql.replace("?", ":{}").format(params.keys().__iter__().next())
            out_style_args.append(params.values())
        elif isinstance(params, Sequence):
            # Ordinal parameter style
            formatted_sql = formatted_sql.replace("?", "_[]").format(params.index(params.__iter__().next()).__iter__().next())
            out_style_args.append(params)

    return (formatted_sql, out_style_args)

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.

    """
    if not path:
        raise ValueError('`path` must be provided')

    path = self.pyfs.get_path(path)
    ocfldir = path.ocfl_dir

    if not ocfldir.object_root.is_dir():
        raise NotADirectoryError('invalid OCFL object root directory')

    for k, v in self.STAGED_FILES.items():
        v.validate(ocfldir)

    for k, v in self.VERSION_HEADERS.items():
        if v.vpath is not None:
            raise KeyError('invalid version header')
        v.validate(ocfldir)

    if ocfldir.version_storage_root is None:
        raise NotADirectoryError('invalid version storage root directory')

    if len(list(ocfldir.version_storage_root.iterdir())) != len(self.VERSION_HEADERS.values()):
        raise NotDirectoryError('mismatched versions')

    return True

def validate(path: str) -> bool:
    """
    Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """

    # 1. Check if path is a pyfs root
    if pyfs.is_root(path):
        return True

    # 2. Check if path includes a YAML content file
    if not path.endswith('.yaml'):
        raise errors.NotAnOCFLObject('not an OCFL object (no YAML file)')

    # 3. Check if YAML file is valid
    try:
        _ = yaml.load(path)
    except yaml.YAMLError as e:
        raise errors.NotAnOCFLObject(f'not an OCFL object ({path})') from e

    # 4. Check if directory structure is valid
    if not os.path.exists(os.path.join(path, 'data')):
        raise errors.OCFLObjectInvalid('invalid directory structure')

    return True

