    existing_path = path_exists(path, force_run=True) # pylint: disable=E1123

    if not existing_path:
        raise ValueError(f"{path} is not a file or directory")

    if os.path.isdir(existing_path):
        allowed_directory = True

    for root, directories, files in os.walk(existing_path):
        if root == existing_path:
            # Skip the root directory
            pass
        elif directories or files:
            raise ValueError(f"{root} must be empty")

    if not allowed_directory:
        # Check for extension
        extension = os.path.splitext(existing_path)[1]
        if extension not in allowed_extensions:
            raise ValueError(f"{existing_path} must have one of these extensions: {allowed_extensions}")

    return True

