def validate_as_prior_version(self, prior):
    """
    Check that the given prior is a valid prior version of the current inventory object.
    The input variable prior is also expected to be an InventoryValidator object.
    Both self and prior inventories are assumed to have been checked for internal consistency.
    """
    if not isinstance(prior, InventoryValidator):
        raise ValueError("The given prior is not an InventoryValidator object")

    if self.inventory.version != prior.inventory.version:
        raise ValueError("The given prior has a different inventory version")

    if self.inventory.name != prior.inventory.name:
        raise ValueError("The given prior has a different inventory name")

    if self.target.name != prior.target.name:
        raise ValueError("The given prior has a different target name")

    if self.target.type != prior.target.type:
        raise ValueError("The given prior has a different target type")

    if self.target.value != prior.target.value:
        raise ValueError("The given prior has a different target value")

    if self.local_values != prior.local_values:
        raise ValueError("The given prior has different local values")

    if self.conditions != prior.conditions:
        raise ValueError("The given prior has different conditions")

    if self.global_parameters != prior.global_parameters:
        raise ValueError("The given prior has different global parameters")

    if self.local_parameters != prior.local_parameters:
        raise ValueError("The given prior has different local parameters")

    return True

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    if not isinstance(prior, InventoryValidator):
        raise ValueError(f"Argument prior must be an instance of InventoryValidator, not {type(prior).__name__}")
    if self.version > prior.version:
        raise ValueError(f"Inventory {self.name} version {self.version} cannot be a prior version of inventory {prior.name} version {prior.version}")
    if self.inventory != prior.inventory:
        raise ValueError(f"Inventories must be identical for prior version check")
    if self.discovery_date > prior.discovery_date:
        raise ValueError(f"Discovery dates must not be in the future for prior version check")
    if self.status == 'active' and prior.status == 'finished':
        raise ValueError(f"Active inventory versions cannot be prior versions of finished versions")
    if (self.status == 'finished' and prior.status == 'active') and (self.date_finished > prior.discovery_date):
        raise ValueError(f"Finished inventory versions with start dates later than the prior version discovery dates cannot be prior versions")
    return

def validate_as_prior_version(self, prior):
    """
