    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Check that the prior and current inventories are of the same type
    if type(self) != type(prior):
        raise ValueError("The prior inventory is not of the same type as the current inventory")

    # Check that the prior and current inventories have the same number of items
    if len(self.items) != len(prior.items):
        raise ValueError("The prior inventory does not have the same number of items as the current inventory")

    # Check that the items in the prior and current inventories are in the same order
    for i in range(len(self.items)):
        if self.items[i] != prior.items[i]:
            raise ValueError("The item at index {} is not the same in the prior and current inventories".format(i))

    # Check that the current inventory has not been modified in a way that would make it invalid
    if self.modified and self.modification_time > prior.modification_time:
        raise ValueError("The current inventory has been modified since the prior inventory was created")

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if version not in inventory or not inventory[version]["local"]:
        raise ValueError("Version {} found in inventory do not have local state".format(version))

    logical_path_map = {}

    for logical_path, md in inventory[version]["metadata"].items():
        logical_path_map[logical_path] = set(md["content_files"])

    return logical_path_map

