    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    xml_files = {}
    with open(zip_path, 'rb') as f:
        zf = zipfile.ZipFile(f)
        for filename in zf.namelist():
            if filename.endswith('.xml'):
                # group files by their XML basename
                basename = os.path.basename(filename)[:-4]
                if basename not in xml_files:
                    xml_files[basename] = []
                xml_files[basename].append(filename)

    # load data from each XML file
    data = {}
    for basename, files in xml_files.items():
        data[basename] = {}
        for filename in files:
            with zf.open(filename) as f:
                data[basename].update(xmltodict.parse(f.read()))

    return data

