def _extract_number_and_supplment_from_issue_element(issue):
    number = None
    suppl = None
    value = issue.text

    if re.match(r'Spe\b', value, re.IGNORECASE):
        number = 1
    elif re.match(r'Supp\b', value, re.IGNORECASE):
        number = 1
    elif re.match(r'Spe\s*1\b', value, re.IGNORECASE):
        number = 1
        suppl = True
    elif re.match(r'Spe\s+1\b', value, re.IGNORECASE):
        number = 1
        suppl = True
    elif re.match(r'Spe\s*(\d+\s?)\b', value, re.IGNORECASE):
        number = int(re.match(r'Spe\s*(\d+)\b', value, re.IGNORECASE).groups()[0])
    elif re.match(r'Supp\s*1\b', value, re.IGNORECASE):
        number = 1
        suppl = True
    elif re.match(r'Supp\s+1\b', value, re.IGNORECASE):
        number = 1
        suppl = True
    elif re.match(r'Supp\s*(\d+\s?)\b', value, re.IGNORECASE):
        number = int(re.match(r'Supp\s*(\d+)\b', value, re.IGNORECASE).groups()[0])
    elif re.match(r'^S(\d+)\b|\b\s*(\d+)\s*', value):
        number = int(re.match(r'^S(\d+)\b|\b\s*(\d+)\s*', value).groups()[0])

    return number, suppl

