def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    new_args = []
    for arg in args:
        if arg.type == '&':
            # Absorption
            if arg[0] == arg[1]:
                new_args.append(arg[0])
            else:
                new_args.append(arg)
        elif arg.type == '|':
            # Negative absorption
            if arg[0] == ~arg[1]:
                new_args.append(arg[0] & arg[1])
            else:
                new_args.append(arg)
        else:
            new_args.append(arg)
    return new_args

def absorb(self, args):
    new_args = []
    for expr in args:
        if expr.op == '|':
            if expr.left.op == '&' and expr.left.left.literal == expr.right.literal:
                new_args.append(expr.left.left)
            elif expr.right.op == '&' and expr.right.left.literal == expr.left.literal:
                new_args.append(expr.right.left)
            else:
                new_args.append(expr)
        elif expr.op == '&':
            if expr.right.op == '~' and expr.right.arg.literal == expr.left.literal:
                new_args.append(Literal(expr.left.literal))
            else:
                new_args.append(expr)
        else:
            new_args.append(expr)
    return new_args

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    new_args = []
    for arg in args:
        if arg.op == '&':
            # Absorption
            if arg.arg1 == arg.arg2:
                new_args.append(arg.arg1)
            else:
                new_args.append(arg)
        elif arg.op == '|':
            # Negative absorption
            if arg.arg1 == ~arg.arg2:
                new_args.append(arg.arg1 & arg.arg2)
            elif arg.arg2 == ~arg.arg1:
                new_args.append(arg.arg1 | arg.arg2)
            else:
                new_args.append(arg)
        else:
            new_args.append(arg)
    return new_args

