def run_command(commands, args=None, cwd=None, verbose=False, hide_stderr=False, env=None):
    """
    Call the given command(s).

    :param commands: The command(s) to call as a string or list of strings.
    :param args: The command arguments as a list of strings.
    :param cwd: The directory in which to run the command.
    :param verbose: If True, print all output.
    :param hide_stderr: If True, hide the stderr output.
    :param env: Environment variables to set for the command.
    """
    if isinstance(commands, str):
        commands = [commands]
    for command in commands:
        try:
            output = subprocess.check_output(command, shell=True, cwd=cwd,
                                             env=env)
            if verbose:
                print(output.decode())
        except subprocess.CalledProcessError as e:
            if not hide_stderr:
                sys.stderr.write(e.output.decode())
            raise

