def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""

    command = " ".join(commands) + " " + " ".join(args)
    if cwd:
        os.chdir(cwd)
    try:
        if env:
            for key, value in env.items():
                os.environ[key] = value
        result = subprocess.check_output(command, shell=True, stderr=subprocess.DEVNULL) if hide_stderr else subprocess.check_output(command, shell=True)
        return result.decode("utf-8")
    except subprocess.CalledProcessError as e:
        if verbose:
            print(e.message)
        return ""
    finally:
        if cwd:
            os.chdir(os.path.join(os.getcwd(), os.pardir))
        if env:
            for key in env.keys():
                os.environ.pop(key, None)

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if isinstance(commands, str):
        commands = [commands]
    if not isinstance(args, list):
        args = [args]
    for i, command in enumerate(commands):
        command = command.split()
        command.extend(args[i])
        command = [str(x) for x in command]
        subprocess.run(command, cwd=cwd, verbose=verbose, check=True, shell=False, stderr=subprocess.PIPE)

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess

    def make_command(command):
        args = shlex.split(command, 1)
        cmd = args.pop(0)
        return (cmd, args)

    def call(command, args, cwd=None, verbose=False, hide_stderr=False, env=None):
        args = [command] + args
        if verbose:
            print('>', ' '.join(args))
        env = {} if env is None else env
        return subprocess.call(args, cwd=cwd, stderr=subprocess.DEVNULL if hide_stderr else None, env=env)

    if isinstance(commands, str):
        commands = [commands]

    for command in commands:
        cmd, args = make_command(command)
        args = [arg.format(**env) for arg in args]
        call(cmd, args, cwd=cwd, verbose=verbose, hide_stderr=hide_stderr, env=env)

