def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    num_objects = 0
    good_objects = 0

    # Iterate over all objects in the hierarchy
    for obj in self.all_objects:
        num_objects += 1

        # Check object against schema
        if validate_objects:
            try:
                self._object_schema.validate(
                    obj,
                    use_defaults=False,
                    coerce_values=False,
                    remove_readonly=False
                )
            except jsonschema.ValidationError as e:
                if show_warnings:
                    print(f"Object {obj['id']} failed validation: {e}")
                continue

        # Check object digest
        if check_digests and "digest" in obj:
            obj_copy = copy.deepcopy(obj)
            del obj_copy["digest"]
            if obj["digest"] != self._object_hash(obj_copy):
                if show_warnings:
                    print(f"Object {obj['id']} has invalid digest")
                continue

        # Object is valid
        good_objects += 1

    return num_objects, good_objects

