def deep_merge_nodes(nodes):
    merged_nodes = []
    for node in nodes:
        if node not in merged_nodes:
            merged_nodes.append(node)
        else:
            for other_node in nodes:
                if node in other_node:
                    merged_nodes.remove(node)
                    node = node.merge(other_node)
                    merged_nodes.append(node)
                    break
    return merged_nodes

def deep_merge_nodes(nodes):
    result = []
    # Iterate over the input nodes
    for node in nodes:
        # Check if the current node is a ScalarNode
        if isinstance(node, ruamel.yaml.nodes.ScalarNode):
            # If it is a ScalarNode, check if it has a mapping value corresponding to a key
            mapping_value = node.value.get(node.key)
            # If the mapping value is not None, add it to the result
            if mapping_value is not None:
                result.append((node, mapping_value))
        # Otherwise, if the current node is a MappingNode, process its value
        elif isinstance(node, ruamel.yaml.nodes.MappingNode):
            # Get the current node's value as a dictionary
            value = node.value
            # Check if the current node's key has already been added to the result
            if node.key in result:
                # If it has, get the previous value corresponding to the key
                previous_value = result[node.key]
                # If the previous value is a MappingNode, deep merge its value with the current node's value
                if isinstance(previous_value, ruamel.yaml.nodes.MappingNode):
                    # Create a new dictionary to hold the merged values
                    merged_value = {}
                    # Iterate over the previous value's keys
                    for key in previous_value:
                        # Check if the current key is also present in the current node's value
                        if key in value:
                            # If it is, deep merge the values corresponding to the key
                            if isinstance(value[key], ruamel.yaml.nodes.MappingNode):
                                merged_value[key] = deep_merge_nodes([value[key], previous_value[key]])
                            # Otherwise, add the previous value's key-value pair to the merged value
                            else:
                                merged_value[key] = previous_value[key]
                # Otherwise, add the previous value to the merged value
                else:
                    merged_value = previous_value
                # Add the merged value to the result
                result.append((node.key, merged_value))
            # If the current node's key has not been added to the result, add it directly
            else:
                result.append((node.key, value))
    return result

def deep_merge_nodes(nodes):
    merged_nodes = {}
    for node in nodes:
        key, value = node
        if key not in merged_nodes:
            merged_nodes[key] = value
        else:
            tmp = merged_nodes[key]
            if isinstance(tmp, dict):
                tmp.update(value)
            elif isinstance(tmp, list):
                tmp.extend(value)
            else:
                merged_nodes[key] = value
    return [
        (key, value) for key, value in merged_nodes.items()
    ]

