def paging(response, max_results):
    if not response:
        raise ValueError("Invalid response received")
    if not max_results:
        raise ValueError("Maximum number of results should be a positive integer")
    if max_results > len(response):
        return response
    result = []
    for i in range(0, len(response), max_results):
        result.append(response[i:i + max_results])
    return result

def paging(response, max_results):
    if response is None:
        raise ValueError("Response must not be None")
    if max_results <= 0:
        raise ValueError("Maximum number of results must be positive")

    current_page = []
    for i, item in enumerate(response):
        if i < max_results:
            current_page.append(item)
        else:
            yield current_page
            current_page = [item]
    if current_page:
        yield current_page

def paging(response, max_results):
