        raise ValueError("Maximum number of results must be positive")
    items = []
    total = len(response)
    for i in range(0, total, max_results):
        page = response[i:i + max_results]
        yield page

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes. Resulting value is an approximation as input value is in most case rounded."""
    units = {'': 1, 'K': 10**3, 'M': 10**6, 'G': 10**9, 'T': 10**12, 'P': 10**15, 'E': 10**18, 'Z': 10**21, 'Y': 10**24}
    size = size.upper()
    num, unit = re.match(r'(?P<num>[0-9.]*)(?P<unit>[KMGTPEZY])?$', size).groups()
    return int(float(num) * units[unit])

def size_to_bytes(size: str) -> int:
    try:
        if 'K' in size:
            return int(float(size.rstrip('K')) * 1024)
        elif 'M' in size:
            return int(float(size.rstrip('M')) * 1024 * 1024)
        elif 'G' in size:
            return int(float(size.rstrip('G')) * 1024 * 1024 * 1024)
        else:
            return int(float(size))
    except ValueError:
        raise ValueError("Invalid input size: {}".format(size))

def size_to_bytes(size: str) -> int:
    if not size:
        raise ValueError("Invalid input size")

    size = size.upper()
    size_num = size[:-1]
    size_unit = size[-1]

    try:
        num = int(size_num)
    except ValueError:
        raise ValueError("Invalid input size")

    if size_unit == 'B':
        result = num
    elif size_unit == 'K':
        result = num * 1024
    elif size_unit == 'M':
        result = num * 1024 * 1024
    elif size_unit == 'G':
        result = num * 1024 * 1024 * 1024
    elif size_unit == 'T':
        result = num * 1024 * 1024 * 1024 * 1024
    elif size_unit == 'P':
        result = num * 1024 * 1024 * 1024 * 1024 * 1024
    elif size_unit == 'E':
        result = num * 1024 * 1024 * 1024 * 1024 * 1024 * 1024
    else:
        raise ValueError("Invalid input size unit")

    return result

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """

    return {k: sum(d[k] for d in dicts) for k in set().union(*dicts)}

def _dictsum(dicts):
    result = {}
    for d in dicts:
        for k, v in d.items():
            if k not in result:
                result[k] = 0
            result[k] += v
