def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    base = len(alphabet)
    if padding is not None and padding > 0:
        number = number.zfill(padding)
    result = ""
    while number > 0:
        result = alphabet[number % base] + result
        number //= base
    return result

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    base = len(alphabet)
    digits = []
    while number > 0:
        digits.append(alphabet[number % base])
        number //= base
    if padding is not None:
        digits = [alphabet[0] for _ in range(padding - len(digits))] + digits
    return ''.join(reversed(digits))

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not isinstance(number, int):
        raise ValueError("number must be an integer")
    if not isinstance(alphabet, list):
        raise ValueError("alphabet must be a list")
    if not all(isinstance(s, str) for s in alphabet):
        raise ValueError("all elements in alphabet must be strings")
    if padding is not None and not isinstance(padding, int):
        raise ValueError("padding must be an integer or None")
    if padding is not None and padding < 0:
        raise ValueError("padding must be non-negative")

    base = len(alphabet)
    if base < 2:
        raise ValueError("alphabet must have at least 2 elements")

    s = ""
    while number > 0:
        rem = number % base
        s = alphabet[rem] + s
        number //= base

    if padding is not None:
        s = padding * alphabet[0] + s

    return s

