def string_to_int(string: str, alphabet: List[str]) -> int:
    if not isinstance(string, str):
        raise ValueError("string must be a string")
    if not isinstance(alphabet, list):
        raise ValueError("alphabet must be a list")

    base = len(alphabet)
    if base < 2:
        raise ValueError("alphabet must contain at least two elements")

    inverse_alphabet = dict(zip(alphabet, range(0, base)))

    n = 0
    exp = 0
    for i in reversed(string):
        n += inverse_alphabet[i] * (base ** exp)
        exp += 1

    return n

def get_repo_archive(url: str, destination_path: Path) -> Path:
    response = requests.get(url, stream=True)
    if response.status_code != 200:
        raise requests.HTTPError(response.status_code, response.reason)

    archive_path = destination_path / url.rsplit('/', 1)[1]
    with open(archive_path, 'wb') as file:
        for chunk in response.iter_content(1024):
            file.write(chunk)

    return archive_path

def regex_dict(item):
    """
    Convert *.cpp keys to regex keys

    Given a dict where the keys are all filenames with wildcards, convert only
    the keys into equivalent regexes and leave the values intact.

    Example:

    rules = {
        '*.cpp':
            {'a': 'arf', 'b': 'bark', 'c': 'coo'},
        '*.h':
            {'h': 'help'}
    }
    regex_keys = regex_dict(rules)

    Args:
        item: dict to convert
    Returns:
        dict with keys converted to regexes
    """
    processed_item = {}
    for key, value in item.items():
        if '*' in key:
            regex_key = re.escape(key).replace('\\*', '.*')
            processed_item[regex_key] = value
        else:
            processed_item[key] = value
    return processed_item

