                               1 for POSIX, 0 for Windows/CMD.

    Returns:
        list: The split string.
    """
    if platform == 'this':
        if re.match(r'ssh|cmd\.exe', s, re.I):
            platform = 0
        else:
            platform = 1

    if platform == 0:
        return re.split(r' +', s, re.M)
