def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    precondition.AssertType(s, Text)

    if platform == 'this':
        platform = get_platform_name()

    if platform == 'this':
        is_windows = False
        if platform == 'Windows' or platform.startswith('win'):
            is_windows = True
        is_posix = False
        if platform == 'POSIX' or platform.startswith('posix'):
            is_posix = True
        if is_windows:
            pattern = r'[^\s"]+|"[^"]*"'
        else:
            pattern = r'[^\s]+'
    elif platform == '1':
        pattern = r'[^\s]+'
    elif platform == '0':
        pattern = r'(["])((?:\\\1|[^\1])+?)(\1|$)'
    else:
        raise ValueError('Invalid platform: ' + platform)

    parts = re.findall(pattern, s)

    if platform == '0':
        parts = [''.join(part[1:-1]) for part in parts]

    return parts

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.

    For use with subprocess, for argv injection etc. Using fast REGEX.

