def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        if os.name == 'posix':
            platform = 1
        else:
            platform = 0

    if platform == 1:
        # Posix
        pattern = r"'[^']*'|\S+"
        return [m.group(0) for m in re.finditer(pattern, s)]
    elif platform == 0:
        # Windows/CMD
        pattern = r"[^\\]""[^""]*[^\\]"|"[^"]*[^"]|"|[^\\][^ ]*[^\\ ]"|[^\s]"
        return [m.group(0) for m in re.finditer(pattern, s)]
    else:
        raise ValueError(f"Invalid platform value {platform}")

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    if not os.path.exists(archive_path):
        raise ValueError(f"The passed archive path \"{archive_path}\" does not exist.")

    extension = os.path.splitext(archive_path)[1]

    if extension == ".tar.gz":
        extract_dir = "."
        command = "tar -xf"
    elif extension == ".tar.bz2":
        extract_dir = "."
        command = "tar -xf"
    elif extension == ".zip":
        extract_dir = os.path.splitext(os.path.basename(archive_path))[0]
        command = "pkunzip"
    else:
        raise ValueError(f"Unsupported archive extension \"{extension}\"")

    target_dir = os.path.join(tmp_path, extract_dir) if tmp_path else extract_dir
    subprocess.run(command + " " + archive_path + " -C " + target_dir)

    if filename is None:
        filename = os.path.splitext(os.path.basename(archive_path))[0]

    return os.path.join(target_dir, filename)

