        return None
    parts = frequency.lower().split()
    if len(parts) != 2:
        raise ValueError("Invalid frequency: {}".format(frequency))
    quantity, unit = parts
    try:
        quantity = int(quantity)
    except ValueError:
        raise ValueError("Invalid quantity: {}".format(quantity))
    if unit == "year":
        return datetime.timedelta(days=quantity * 365)
    elif unit == "month":
        return datetime.timedelta(days=quantity * 30)
    elif unit == "week":
        return datetime.timedelta(days=quantity * 7)
    elif unit == "day":
        return datetime.timedelta(days=quantity)
    elif unit == "hour":
        return datetime.timedelta(hours=quantity)
    elif unit == "minute":
        return datetime.timedelta(minutes=quantity)
    elif unit == "second":
        return datetime.timedelta(seconds=quantity)
    else:
        raise ValueError("Invalid unit: {}".format(unit))

