def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    if not matcher.group(1) in os.environ:
        if matcher.group(2) is None:
            raise EnvironmentError("The variable {} is not defined in the environment.".format(matcher.group(1)))
        else:
            return matcher.group(2)
    return os.environ[matcher.group(1)]

def _resolve_string(matcher):
    name = matcher.group(1)
    default = matcher.group(2) or None
    if name not in os.environ:
        if default is not None:
            return default
        raise EnvironmentError(f"Variable {name} is not defined in the environment")
    return os.environ[name]

def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    name_default = matcher.group(1)
    name, default = name_default.split(":", 1)
    if not name:
        raise Exception("Missing name")
    if default:
        return os.environ.get(name, default)
    return os.environ[name]

