def from_ticks(cls, ticks, tz=None):
    ticks = int(ticks)
    if not 0 <= ticks < 86400000000000:
        raise ValueError("Ticks must be between 0 and 86,399,999,999,999")
    datetime_ = datetime.datetime(1970, 1, 1, tzinfo=cls.utc_tz)
    datetime_ += datetime.timedelta(microseconds=ticks / 1000)
    if tz is not None:
        datetime_ = datetime_.astimezone(tz)
    return cls(datetime_)

