def _get_seq_with_type(seq, bufsize=None):
    if not isinstance(seq, Sequence):
        seq = list(seq)
    if bufsize is None:
        return (seq, type(seq))
    return ([seq], type(seq))

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    if isinstance(seq, str):
        return (seq, str)
    elif isinstance(seq, list):
        return (seq, list)
    elif isinstance(seq, tuple):
        return (seq, tuple)
    elif hasattr(seq, "read"):
        if hasattr(seq, "seek") and not hasattr(seq, "isatty") and bufsize is None:
            return (seq, type(seq))
        else:
            return (seq, "string")
    else:
        try:
            return (seq, type(seq))
        except Exception:
            raise TypeError("Object of type %s is not of any sequence type." % (str(type(seq))))

