def hist_to_graph(hist, make_value=None, get_coordinate="left", field_names=("x", "y"), scale=None):
    # Define a function to create a graph point from a histogram bin
    def make_point(bin_):
        # Get the bin's coordinate
        if get_coordinate == "left":
            coordinate = bin_.left
        elif get_coordinate == "right":
            coordinate = bin_.right
        else:
            coordinate = (bin_.left + bin_.right) / 2
        # Get the value of the point from make_value
        if make_value is None:
            value = bin_.content
        else:
            value = make_value(bin_)
        # Create a dictionary with the field names and corresponding values
        point = {name: value[i] for i, name in enumerate(field_names)}
        # Add the coordinate as an additional field
        point["coord"] = coordinate
        return point
    # Create a graph with the same number of dimensions as the histogram
    graph = [[] for _ in range(hist.dimension)]
    # Iterate over all bins of the histogram
    for bin_ in hist:
        # Create a graph point from the current bin
        point = make_point(bin_)
        # Add the point to the corresponding dimension of the graph
        graph[bin_.dimension].append(point)
    # Set the scale of the graph
    if scale is True:
        graph.scale = hist.scale
    elif isinstance(scale, (list, tuple)):
        graph.scale = [scale[i] for i in graph.dimension]
    return graph

