    if num_fields != num_dim:
        raise ValueError("Incorrect number of fields")
    if make_value is None:
        make_value = lambda bin_: bin_.content
    points = [[] for _ in range(num_fields)]

    def get_bin_value(bin_):
        value = make_value(bin_)
        if isinstance(value, tuple):
            value = list(value)
        else:
            value = [value]
        if get_coordinate == "left":
            value.insert(0, bin_.left)
        elif get_coordinate == "right":
            value.insert(0, bin_.right)
        else:
            value.insert(0, bin_.center)
        return value

    for bin_ in hist:
        value = get_bin_value(bin_)
        for point, val in zip(points, value):
            point.append(val)
    graph = Graph(points, field_names=field_names, scale=scale)
    return graph

def _verify(iface, candidate, tentative=False, vtype=None):
    """
    Verify that *candidate* might correctly provide *iface*.
    This involves:
    - Making sure the candidate claims that it provides the interface using `iface.providedBy` (unless *tentative* is `True`, in which case this step is skipped). This means that the candidate's class declares that it `implements <zope.interface.implementer>` the interface, or the candidate itself declares that it `provides <zope.interface.provider>` the interface
    - Making sure the candidate defines all the necessary methods
    - Making sure the methods have the correct signature (to the extent possible)
    - Making sure the candidate defines all the necessary attributes
    :return bool: Returns a true value if everything that could be checked passed.
    :raises zope.interface.Invalid: If any of the previous conditions does not hold.
    """
    if not tentative and not iface.providedBy(candidate):
        raise Invalid("Candidate {} does not claim to provide {}".format(candidate, iface))
    for key, spec in iface.namesAndDescriptions():
        if spec.__name__ == '_':
            continue
        try:
            method = getattr(candidate, spec.__name__)
        except AttributeError:
            raise Invalid("Candidate {} does not define method {}".format(candidate, spec.__name__))
        try:
            assert spec.bound().co_firstlineno == method.bound().co_firstlineno
            assert spec.bound().co_argcount == method.bound().co_argcount
            for i in range(spec.bound().co_argcount):
                assert spec.bound().co_varnames[i] in method.bound().co_varnames
                if spec.bound().co_varnames[i] in {'self'} and spec.bound().co_argcount > 0:
                    assert spec.bound().co_varnames[i] in method.bound().co_varnames
        except AssertionError:
            raise Invalid("Signature mismatch for method {}.{}{}".format(candidate, spec.__name__, spec.bound()))
    return True

def verifyObject(iface, candidate, tentative=False):
    def _checkIface(candidate):
        """Check if the candidate claims that it provides the interface."""
        if not tentative:
            if not iface.providedBy(candidate):
                raise Invalid(f"The object {candidate} does not provide the interface {iface}.")
        return True

    def _checkMethods(candidate):
        """Check if the candidate defines all the necessary methods."""
        for method in iface.names():
            if not hasattr(candidate, method):
                raise Invalid(f"The object {candidate} does not define the required method {method}.")
        return True

    def _checkSignatures(candidate):
        """Check if the candidate defines all the necessary attributes."""
        for attr in iface.names():
            if not hasattr(candidate, attr):
                raise Invalid(f"The object {candidate} does not define the required attribute {attr}.")
        return True

    return (_checkIface(candidate) and
            _checkMethods(candidate) and
            _checkSignatures(candidate))

def verifyObject(iface, candidate, tentative=False):
    provided = iface.providedBy(candidate)
    if not provided and not tentative:
        raise zope.interface.Invalid("Candidate does not claim to implement the interface")

    methods = iface.getMethods()
    for name, method in methods.items():
        if not hasattr(candidate, name):
            raise zope.interface.Invalid("Candidate does not define required method %s" % name)
        candidate_method = getattr(candidate, name)
        args = method.getSignature().arguments
        kwargs = method.getSignature().keywords
        if len(args) > 0 or len(kwargs) > 0:
            raise zope.interface.Invalid("Candidate method %s has keyword arguments, which are not supported" % name)

    attributes = iface.getAttributes()
    for name, attribute in attributes.items():
        if not hasattr(candidate, name):
            raise zope.interface.Invalid("Candidate does not define required attribute %s" % name)
        candidate_attribute = getattr(candidate, name)
        if not isinstance(candidate_attribute, attribute.getType()):
            raise zope.interface.Invalid("Candidate attribute %s has incorrect type" % name)

    return True

def verifyObject(iface, candidate, tentative=False):
    """
    Verify that *candidate* might correctly provide *iface*.

    :param iface: The interface to be checked.
    :type iface: Zope Interface
    :param candidate: The object to check.
    :type candidate: object
    :param tentative: If `True`, skip the *providedBy* check.
    :type tentative: bool
    :return: Returns `True` if everything that could be checked passed.
    :rtype: bool
    :raises zope.interface.Invalid: If any of the previous conditions does not hold.
    """
    # Check that the candidate declares that it provides the interface using iface.providedBy
    if not tentative and not iface.providedBy(candidate):
        raise zope.interface.Invalid(
            "{} does not provide the interface".format(candidate)
        )
    # Check that the candidate has all the necessary methods
    for name, method in iface.methods.items():
        try:
            method.__get__(candidate)
        except AttributeError:
            raise zope.interface.Invalid(
                "{} does not define the method {}".format(candidate, name)
            )
    # Check that the methods have the correct signature
    for name, method in iface.methods.items():
        candidate_method = getattr(candidate, name)
        if zope.interface.signature(candidate_method) != zope.interface.signature(method):
            raise zope.interface.Invalid(
                "{} has an incorrect signature for the method {}".format(candidate, name)
            )
    # Check that the candidate has all the necessary attributes
    for name, types in iface.attributes.items():
        try:
            value = getattr(candidate, name)
        except AttributeError:
            raise zope.interface.Invalid(
                "{} does not define the attribute {}".format(candidate, name)
            )
        if not types.isValid(value):
            raise zope.interface.Invalid(
                "{} has an incorrect value for attribute {}".format(candidate, name)
            )
    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if not isinstance(candidate, type):
        raise ValueError("candidate must be a class")

    # Make sure the candidate has a __base__
    if not hasattr(candidate, "__bases__"):
        raise ValueError("candidate must have a __base__")

    # Make sure the candidate has the right __bases__
    if iface not in candidate.__bases__:
        raise ValueError("candidate does not inherit from " + str(iface))

    # Make sure the candidate has the right method definitions
    for method in iface.methods(tentative=tentative):
        if method not in candidate.method_definition:
            raise ValueError("candidate does not implement method " + str(method))

    # Make sure the candidate has the right property definitions
    for prop in iface.properties(tentative=tentative):
        if prop not in candidate.property_definition:
            raise ValueError("candidate does not implement property " + str(prop))

    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    # Check if the candidate has all the methods specified in the interface
    for method in iface.methods:
        if not hasattr(candidate, method):
            raise VerificationError("Candidate {} does not have method {}"
                                    .format(candidate, method))

    # Check if the candidate has all the properties specified in the interface
    for prop in iface.properties:
        if not hasattr(candidate, prop):
            raise VerificationError("Candidate {} does not have property {}"
                                    .format(candidate, prop))

    # Check if the candidate has all the attributes specified in the interface
    for attr in iface.attributes:
        if not hasattr(candidate, attr):
            raise VerificationError("Candidate {} does not have attribute {}"
                                    .format(candidate, attr))

    # Check if the candidate has all the functions specified in the interface
    for func in iface.functions:
        if not hasattr(candidate, func):
            raise VerificationError("Candidate {} does not have function {}"
                                    .format(candidate, func))

    # Check if the candidate has all the classes specified in the interface
    for cls in iface.classes:
        if not isinstance(candidate, cls):
            raise VerificationError("Candidate {} is not an instance of {}"
                                    .format(candidate, cls))

    # Check if the candidate has all the interfaces specified in the interface
    for interface in iface.interfaces:
        if not verifyClass(interface, candidate, tentative):
            raise VerificationError("Candidate {} does not implement {}"
                                    .format(candidate, interface))

    # Verify all the method's return type
    for method in iface.methods:
        method_func = getattr(candidate, method)
        if not verifyReturn(method_func(), iface.methods[method]['return']):
            raise VerificationError("Return value of method "
                                    "{} does not meet the specification{}".format(
                                    method, iface.methods[method]['return']))

    # Verify all the methods' arguments
    for method in iface.methods:
        method_func = getattr(candidate, method)
        args = inspect.getfullargspec(method_func).args[1:]
        method_args = iface.methods[method]['args']
        for i, arg in enumerate(args):
            if not verifyArgument(arg, method_args[i]):
                raise VerificationError("Arguments of method "
                                        "{} does not meet the specification{}"
                                        .format(method, method_args[i]))

    # Verify all the properties' types
    for prop in iface.properties:
        prop_value = getattr(candidate, prop)
        if not verifyReturn(prop_value, iface.properties[prop]['type']):
            raise VerificationError("Type of property {} mismatch"
                                    .format(prop))

    # Verify all the attributes' types
    for attr in iface.attributes:
        attr_value = getattr(candidate, attr)
        if not verifyReturn(attr_value, iface.attributes[attr]['type']):
            raise VerificationError("Type of attribute {} mismatch"
                                    .format(attr))

    # Verify all the functions' return types
    for func in iface.functions:
        func_value = getattr(candidate, func)
        if not verifyReturn(func_value, iface.functions[func]['return']):
            raise VerificationError("Return type of function {} mismatch"
                                    .format(func))

    # Verify all the functions' arguments
    for func in iface.functions:
        func_value = getattr(candidate, func)
        args = inspect.getfullargspec(method_func).args[1:]
        func_args = iface.functions[func]['args']
        for i, arg in enumerate(args):
            if not verifyReturn(arg, func_args[i]['type']):
                raise VerificationError("Type of arguments {} mismatch"
                                        .format(func))

    # Verify that the candidate has all the attributes, functions and methods
    # specified in the interface
    for attr in iface.attributes:
        if not hasattr(candidate, attr):
            raise VerificationError("Candidate does not have attribute {}"
                                    .format(attr))
    for func in iface.functions:
        if not hasattr(candidate, func):
            raise VerificationError("Candidate does not have function {}"
                                    .format(func))
    for method in iface.methods:
        if not has_method(candidate, method):
            raise VerificationError("Candidate does not have method {}"
                                    .format(method))

    # Verify that the candidate has all the interfaces, properties and methods
    # specified in the interface
    for interface in iface.interfaces:
        if not verifyClass(interface, candidate, tentative):
            raise VerificationError("Candidate does not have interface {}"
                                    .format(interface))
    for prop in iface.properties:
        if not verifyObject(getattr(candidate, prop), iface.properties[prop]):
            raise VerificationError("Candidate does not have property {}"
                                    .format(prop))
    for method in iface.methods:
        if not verifyObject(getattr(candidate, method), iface.methods[method]):
            raise VerificationError("Candidate does not have method {}"
                                    .format(method))

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if isinstance(candidate, iface):
        return candidate
    else:
        raise InvalidArgumentValueError("{} is not an instance of {}".format(candidate, iface))

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    # Check if the candidate has the required interface
    if hasattr(candidate, iface.__name__):
        # Check the argument types of the method
        for mname in iface.__subclasses__():
            m = getattr(iface, mname, None)
            if m:
                # Check if the method exists in the candidate
                if not hasattr(candidate, mname):
                    raise InterfaceError('The candidate does not have the method "{}".'.format(mname))
                # Check if the method parameters match
                candidatemethod = getattr(candidate, mname)
                if candidatemethod.__code__.co_argcount != m.__code__.co_argcount:
                    raise InterfaceError('The method {} has different number of parameters'.format(mname))
                for i in range(m.__code__.co_argcount):
                    if candidatemethod.__code__.co_varnames[i] != m.__code__.co_varnames[i]:
                        raise InterfaceError('The method {} has different parameter names'.format(mname))
        # TODO: check method implementation, including the behavior and exceptions
    else:
        raise InterfaceError('The candidate does not have the required interface.')

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if type(candidate) is not iface:
        raise ValueError("Candidate type {} is not instance "
                         "of iface {}".format(type(candidate), iface))
    if not hasattr(candidate, '__dict__'):
        raise ValueError("Candidate of type {} has no attribute "
                         "__dict__".format(type(candidate)))
    for name in iface.__dict__.keys():
        if callable(getattr(iface, name)):
            if not hasattr(candidate, name):
                raise ValueError("Candidate type {} does not implement "
                                 "method {} from iface {}".format(
                                     type(candidate), name, iface))
            candidate_method = getattr(candidate, name)
            if not callable(candidate_method):
                raise ValueError("Candidate type {} does not implement "
                                 "method {} as callable from iface {}".format(
                                     type(candidate), name, iface))
    return candidate

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc
    for base in bases:
        try:
            base_metaclass = getattr(base, '__metaclass__', None)
        except AttributeError:
            continue
        if base_metaclass is not None:
            return base_metaclass
    return type

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    bases = list(bases)
    if explicit_mc is not None:
        bases.append(explicit_mc)
    for base in bases:
        try:
            if base._metaclass is not None:
                return base._metaclass
        except AttributeError:
            pass
    return None

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    metaclass = None
    if explicit_mc:
        if not issubclass(explicit_mc, type):
            raise TypeError("explicit metaclass must be a class")
        metaclass = explicit_mc
    else:
        for base in bases:
            base_metaclass = getattr(base, "__metaclass__", None)
            if base_metaclass:
                if not issubclass(base_metaclass, type):
                    raise TypeError("base's __metaclass__ must be a class")
                if not metaclass or issubclass(base_metaclass, metaclass):
                    metaclass = base_metaclass
    if not metaclass:
        metaclass = base.__class__
    return metaclass

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    # If an explicit metaclass was provided and is not None, use it
    if explicit_mc is not None:
        return explicit_mc

    # If only one base type is given, use it as the metaclass
    if len(bases) == 1:
        return bases[0]

    # If one or more bases were given, use a class that inherits from all of them
    return type('MetaClass', tuple(bases), {})

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    cls = bases[0]
    if explicit_mc is not None:
        return explicit_mc
    while True:
        if '__metaclass__' in cls.__dict__:
            return cls.__dict__['__metaclass__']
        if cls.__class__ == type or len(cls.__bases__) == 0:
            return type
        cls = cls.__bases__[0]

def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    value = self.get(key)
    self._redis.delete(key)
    if value is None:
        if default is not __marker:
            return default
        else:
            raise KeyError(key)
    return value

def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    if key not in self:
        if default is not __marker:
            return default
        raise KeyError(key)
    for map in [self._pb.IntMap, self._pb.FloatMap, self._pb.StringMap, self._pb.BoolMap]:
        if key in map.keys():
            return map.pop(key)

def pop(self, key, default=__marker):
        """
        D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
        If key is not found, d is returned if given, otherwise KeyError is raised.
        """
        if key not in self:
            if default != __marker:
                return default
            raise KeyError(key)
        if key in self.IntMap.keys():
            return self.IntMap.pop(key)
        if key in self.FloatMap.keys():
            return self.FloatMap.pop(key)
        if key in self.StringMap.keys():
            return self.StringMap.pop(key)
        if key in self.BoolMap.keys():
            return self.BoolMap.pop(key)
        return _marker

