def parse(timestr, default=None, ignoretz=False, tzinfos=None, **kwargs):
    """
    Parse the date/time string into a datetime.datetime object.

    :param timestr: Any date/time string using the supported formats.
    :param default: The default datetime object, if this is a datetime object and not None, elements specified in timestr replace elements in the default object.
    :param ignoretz: If set True, time zones in parsed strings are ignored and a naive datetime.datetime object is returned.
    :param tzinfos: Additional time zone names / aliases which may be present in the string. This argument maps time zone names (and optionally offsets from those time zones) to time zones. This parameter can be a dictionary with timezone aliases mapping time zone names to time zones or a function taking two parameters (tzname and tzoffset) and returning a time zone.

    :return: Returns a datetime.datetime object or, if the fuzzy_with_tokens option is True, returns a tuple, the first element being a datetime.datetime object, the second a tuple containing the fuzzy tokens.
    """

    if default is not None and isinstance(default, datetime.datetime):
        fmt = default
    else:
        fmt = datetime.datetime.utcfromtimestamp(0)
    vals = {}
    for key, val in zip(['year', 'month', 'day', 'hour', 'minute', 'second'], [fmt.year, fmt.month, fmt.day, fmt.hour, fmt.minute, fmt.second]):
        vals[key] = val
    string_parts = timestr.split()
    for key, val in zip(['year', 'month', 'day', 'hour', 'minute', 'second'], string_parts):
        vals[key] = int(val)
        if key == 'second':
            # format 'yyyy-mm-dd hh:mm:ss'
            if not isinstance(val, str):
                raise ValueError("Invalid format")
            if len(val) < 1 or len(val) > 19:
                raise ValueError("Invalid format")
            if val.count('-') != 2:
                raise ValueError("Invalid format")
            if val.count(':') != 2:
                raise ValueError("Invalid format")
        elif key == 'minute':
            # format 'yyyy-mm-dd hh:mm:ssZ'
            if not isinstance(val, str):
                raise ValueError("Invalid format")
            if len(val) < 1 or len(val) > 19:
                raise ValueError("Invalid format")
            if val.count('-') != 2:
                raise ValueError("Invalid format")
            if val.count(':') != 2:
                raise ValueError("Invalid format")
            if val[-1] != 'Z':
                raise ValueError("Invalid format")
        elif key == 'hour':
            # format 'yyyy-mm-dd hh:mm:ss+zz:zz' or 'yyyy-mm-dd hh:mm:ss-zz:zz'
            if not isinstance(val, str):
                raise ValueError("Invalid format")
            if len(val) < 1 or len(val) > 19:
                raise ValueError("Invalid format")
            if val.count('-') != 2:
                raise ValueError("Invalid format")
            if val.count('+') != 1 and val.count('-') != 1:
                raise ValueError("Invalid format")
            if val.count(':') != 2:
                raise ValueError("Invalid format")
        elif key == 'day':
            # format 'yyyy-mm-dd hh:mm:ssZ or yyyy-mm-dd hh:mm:ss+zz:zz'
            if not isinstance(val, str):
                raise ValueError("Invalid format")
            if len(val) < 1 or len(val) > 19:
                raise ValueError("Invalid format")
            if val.count('-') != 2:
                raise ValueError("Invalid format")
            if val.count('+') != 0 and val.count('-') != 0:
                raise ValueError("Invalid format")
            if val.count(':') != 0:
                raise ValueError("Invalid format")
        elif key == 'month':
            # format 'yyyy-mm-dd hh:mm:ssZ'
            if not isinstance(val, str):
                raise ValueError("Invalid format")
            if len(val) < 1 or len(val) > 19:
                raise ValueError("Invalid format")
            if val.count('-') != 2:
                raise ValueError("Invalid format")
            if val.count(':') != 2:
                raise ValueError("Invalid format")
            if val[-1] != 'Z':
                raise ValueError("Invalid format")
        elif key == 'year':
            # format 'yyyy-mm-dd hh:mm:ssZ'
            if not isinstance(val, str):
                raise ValueError("Invalid format")
            if len(val) < 1 or len(val) > 19:
                raise ValueError("Invalid format")
            if val.count('-') != 2:
                raise ValueError("Invalid format")
            if val.count(':') != 2:
                raise ValueError("Invalid format")
            if val[-1] != 'Z':
                raise ValueError("Invalid format")

    # check for time zone
    if '+' in vals['second']:
        # parse 'yyyy-mm-dd hh:mm:ss+zz:zz'
        if len(vals['second']) != 25:
            raise ValueError("Invalid format")
        vals['second'] = vals['second'][:-6]
        timezone = 'GMT' + vals['second'][11:]
        vals['second'] = vals['second'][:10]
    elif '-' in vals['second']:
        # parse 'yyyy-mm-dd hh:mm:ss+zz:zz'
        if len(vals['second']) != 25:
            raise ValueError("Invalid format")
        vals['second'] = vals['second'][:-6]
        timezone = 'GMT' + vals['second'][11:]
        vals['second'] = vals['second'][:10]
    elif vals['second'][-1] == 'Z':
        # parse 'yyyy-mm-dd hh:mm:ss+zz:zz'
        if len(vals['second']) != 22:
            raise ValueError("Invalid format")
        timezone = 'UTC'
        vals['second'] = vals['second'][:20]
    else:
        raise ValueError("Invalid format")

    if ignoretz is True:
        vals['second'] = datetime.datetime.utcfromtimestamp(0).replace(year=vals['year'], month=vals['month'], day=vals['day'], hour=vals['hour'], minute=vals['minute'], second=vals['second']).replace(tzinfo=timezone)
    elif tzinfos is not None:
        if isinstance(tzinfos, dict):
            if timezone in tzinfos.keys():
                timezone = tzinfos[timezone]
                vals['second'] = datetime.datetime.utcfromtimestamp(0).replace(year=vals['year'], month=vals['month'], day=vals['day'], hour=vals['hour'], minute=vals['minute'], second=vals['second']).replace(tzinfo=timezone)
        elif callable(tzinfos):
            tzinfos(timezone, vals['hour'])
        else:
            raise ValueError('tzinfos must be a dictionary or a function')

    return vals['second']

def parse(self, timestr, default=None, ignoretz=False, tzinfos=None, **kwargs):
    """
    Parse the date/time string into a datetime object.

    :param timestr: Any date/time string using the supported formats.
    :param default: The default datetime object, if this is a datetime object and not None, elements specified in timestr replace elements in the default object.
    :param ignoretz: If set True, time zones in parsed strings are ignored and a naive datetime object is returned.
    :param tzinfos: Additional time zone names / aliases which may be present in the string. This argument maps time zone names (and optionally offsets from those time zones) to time zones. This parameter can be a dictionary with timezone aliases mapping time zone names to time zones or a function taking two parameters (tzname and tzoffset) and returning a time zone. The timezones to which the names are mapped can be an integer offset from UTC in seconds or a tzinfo object. This parameter is ignored if ignoretz is set.
    :param \\*\\*kwargs: Keyword arguments as passed to _parse().
    :return: Returns a datetime object or, if the fuzzy_with_tokens option is True, returns a tuple, the first element being a datetime object, the second a tuple containing the fuzzy tokens.
    :raises ParserError: Raised for invalid or unknown string format, if the provided tzinfo is not in a valid format, or if an invalid date would be created.
    :raises TypeError: Raised for non-string or character stream input.
    :raises OverflowError: Raised if the parsed date exceeds the largest valid C integer on your system.
    """
    if not isinstance(timestr, str):
        raise TypeError("timestr must be a string")
    if default is not None and not isinstance(default, datetime.datetime):
        raise TypeError("default must be a datetime object")
    if ignoretz and tzinfos:
        raise ValueError("ignoretz and tzinfos cannot both be True")
    # Parse the timestr
    res = self._parse(timestr, **kwargs)
    # Output a datetime object
    datetime_obj = datetime.datetime(res[0], res[1], res[2], res[3], res[4], res[5], res[6], res[7])
    if ignoretz:
        return datetime_obj
    else:
        if tzinfos:
            if isinstance(tzinfos, dict):
                tzname = tzinfos.get(res[-1])
            else:
                tzname = tzinfos(res[-1], res[8])
            return datetime_obj.astimezone(tzname)
        else:
            return datetime_obj.astimezone(self.default)

def parse(timestr, default=None, ignoretz=False, tzinfos=None, **kwargs):
    try:
        if default is not None and isinstance(default, datetime.datetime):
            d = default
        else:
            d = datetime.datetime.utcnow().replace(tzinfo=pytz.UTC)
        parsed, _ = _parse(timestr, d, ignoretz=ignoretz, tzinfos=tzinfos, **kwargs)
        return parsed.replace(tzinfo=None)
    except ParserError as e:
        raise e
    except TypeError:
        raise TypeError("input must be a string, not {}".format(type(timestr)))

def fromutc(self, dt):
    """
    Given a timezone-aware datetime in a given timezone, calculates a
    timezone-aware datetime in a new timezone.

    Since this is the one time that we *know* we have an unambiguous
    datetime object, we take this opportunity to determine whether the
    datetime is ambiguous and in a "fold" state (e.g. if it's the first
    occurrence, chronologically, of the ambiguous datetime).

    :param dt:
        A timezone-aware :class:`datetime.datetime` object.
    """
    if not dt.tzinfo:
        raise ValueError("'dt' must be a timezone-aware datetime object")
    if not self.normalize(dt):
        raise ValueError("'dt' must be a valid datetime in this timezone")
    if self._is_dst_transition(dt):
        header = "From{}/UTC".format(self.key)
        if self._utc_offset(dt) > 0:
            header += "+"
        else:
            header += "-"
        raise AmbiguousTimeError(header, dt.tzname(), str(self))
    if self._pre_trans[dt]:
        return self._pre_trans[dt]
    if self._std_offset(dt) < self._utc_offset(dt):
        dt += timedelta(seconds=self._transition_delta(dt))
        if self._tzname(dt) == dt.tzname():
            self._pre_trans[dt] = None
        else:
            self._pre_trans[dt] = dt
    return dt

def fromutc(self, dt):
    if isinstance(dt, dateime.datetime):
        # Check whether the datetime is in the timezone given by self.timezone
        if dt.tzinfo is None:
            # If the datetime is naive, assume it's in localtime and convert it to UTC
            dt = dt.replace(tzinfo=_get_current_timezone())
        return self.localize(dt.astimezone(_get_current_timezone()))
    else:
        raise TypeError("fromutc() argument should be a datetime.datetime object, not {}" dt)

def default_tzinfo(dt, tzinfo):
    if isinstance(dt, datetime.datetime) and not dt.tzinfo:
        return dt.replace(tzinfo=tzinfo)
    return dt

