def find_tags(text, replacer=None):
    tags = set()
    lines = text.split("\n")
    in_code_block = False
    for line in lines:
        if line.startswith("```"):
            in_code_block = not in_code_block
            continue
        if not in_code_block:
            for word in line.split():
                if word.startswith("@"):
                    tags.add(word)
                if replacer:
                    line = line.replace(word, replacer(word))
    return tags, "\n".join(lines)

def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    tags = set()
    lines = text.split("\n")
    code_block = False
    for line in lines:
        if line.strip().startswith("```"):
            code_block = not code_block
            continue
        if not code_block:
            for word in line.split():
                if word.startswith("#") and word[1:].isalpha():
                    tags.add(word[1:])
    if replacer is not None:
        for tag in tags:
            text = text.replace(tag, replacer(tag))
    return tags, text

def find_tags(text, replacer=None):
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    tags = set()
    in_code_block = False
    output = ""
    for line in text.splitlines():
        if line.startswith("```"):
            in_code_block = not in_code_block
            output += line + "\n"
            continue
        if in_code_block:
            output += line + "\n"
            continue
        for word in line.split():
            if word.startswith("#"):
                tag = word[1:]
                tags.add(tag)
                if replacer:
                    output += replacer(tag) + " "
                else:
                    output += word + " "
            else:
                output += word + " "
        output += "\n"
    return tags, output.strip()

def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """

    tags = set()

    in_code_block = False

    lines = text.split("\n")

    for line in lines:
        words = line.split()

        for word in words:
            if word.startswith("`"):
                in_code_block = not in_code_block

            if not in_code_block and word.startswith("#"):
                tags.add(word[1:].strip())

                if replacer:
                    line = line.replace(word, replacer(word[1:]))

    return tags, text

