def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""

    # Initialize a dictionary to store the text to link mappings
    text_to_link = {}

    # Define a function to convert text to a link
    def convert_text_to_link(match):
        # If the text is already a link, return it
        if match.group(0).startswith(('http://', 'https://')):
            return match.group(0)
        # If the text is a relative path, turn it into an absolute path
        elif match.group(0).startswith('/'):
            return '/browse/' + match.group(0)
        # If the text is a target, return a link to a file with the specified path
        elif match.group(0).endswith('target'):
            return '/browse/' + match.group(0)
        # Otherwise, return None
        else:
            return None

    # Define a function to add attributes to links
    def add_link_attributes(url, text):
        # If the URL is not None, add a target attribute
        if url is not None:
            return '<a target="_blank" href="{}">{}</a>'.format(url, text)
        # Otherwise, return the original text
        else:
            return text

    # Use the regex pattern to find occurrences of links in the text
    for match in re.finditer(r'''(?P<text>@\w*\s{0,}\w*)|(?P<url>(https?|ftp)://\-\.\w+\.\w{2,4}/\-\.\w+\.\w{2,4}/\-\.\w+\.\w{2,4}/\-)|(?P<path>(?:[^/]+\/)*[^/]+)|(?P<target>\(\w+/\w+\))''', text):
        # If the match is a URL, add it to the text to link dictionary
        if match.group('url'):
            text_to_link[match.group('url')] = None
        # If the match is a path, turn it into an absolute path and add it to the text to link dictionary
        elif match.group('path'):
            text_to_link[match.group('path')] = '/browse/' + match.group('path')
        # If the match is a target, turn it into a link and add it to the text to link dictionary
        elif match.group('target'):
            text_to_link[match.group('target')] = '/browse/' + match.group('target')
        # Otherwise, try to convert the text to a link
        else:
            text_to_link[match.group('text')] = convert_text_to_link(match)

    # Iterate over the text to link dictionary and add attributes to the links
    for key, value in text_to_link.items():
        text_to_link[key] = add_link_attributes(value, key)

    # Return the processed text
    return ''.join(text_to_link.values())

def process_text_links(text):
    memoized_urls = {}
    def memoized_to_url(m):
        value = memoized_urls.get(m.group(0), _NO_URL)
        if value is _NO_URL:
            value = to_url(m)
            memoized_urls[m.group(0)] = value
        return value

    def to_url(m):
        if m.group(1):
            return m.group(0)  # It's an http(s) url.
        path = m.group(0)

        if path.startswith('/'):
            path = os.path.relpath(path, buildroot)
        elif path.startswith('..'):
            # The path is not located inside the buildroot, so it's definitely not a BUILD file.
            return None
        else:
            # The path is located in the buildroot: see if it's a reference to a target in a BUILD file.
            parts = path.split(':')
            if len(parts) == 2:
                putative_dir = parts[0]
            else:
                putative_dir = path
            if os.path.isdir(os.path.join(buildroot, putative_dir)):
                build_files = list(BuildFile.get_build_files_family(
                  FileSystemProjectTree(buildroot),
                  putative_dir))
                if build_files:
                    path = build_files[0].relpath
                else:
                    return None

        if os.path.exists(os.path.join(buildroot, path)):
            # The reporting server serves file content at /browse/<path_from_buildroot>.
            return '/browse/{}'.format(path)
        else:
            return None

    def maybe_add_link(url, text):
        return '<a target="_blank" href="{}">{}</a>'.format(url, text) if url else text

    return _PATH_RE.sub(lambda m: maybe_add_link(memoized_to_url(m), m.group(0)), text)

def fetch_content_type(url: str) -> Optional[str]:
    """
    Fetch the HEAD of the remote url to determine the content type.
    """
    req = urllib2.Request(url, headers={'Host': url.netloc})
    resp = None
    try:
        resp = urllib2.urlopen(req)
        return resp.info().get('content-type', None)
    except HTTPError as e:
        if e.code != 200:
            return None
        else:
            raise e
    finally:
        if resp is not None:
            resp.close()

def fetch_content_type(url: str) -> Optional[str]:
    scheme, netloc, path, query, fragment = urlparse.urlsplit(url)
    if not scheme in ('http', 'https', 'ftp', 'ftps'):
        return None
    req = Urllib2HeadRequest(url, headers={'Host': netloc})
    resp = urlopen(req)
    try:
        if hasattr(resp, 'code') and resp.code != 200 and scheme not in ('ftp', 'ftps'):
            return None
        return resp.info().get('content-type', '')
    finally:
        resp.close()
    return None

