def parse_diaspora_webfinger(document: str) -> dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        json_doc = json.loads(document)
        return parse_diaspora_webfinger(json_doc)
    except json.JSONDecodeError:
        try:
            return parse_diaspora_webfinger_xrd(document)
        except Exception:
            return None

def parse_diaspora_webfinger(document: str) -> Dict:
    if document.startswith("<?xml"):
        # Old format
        root = etree.fromstring(document)
        namespace = root.tag.split("}")[0] + "}"
        nodes = root.xpath(f"//{namespace}AdiunaResource", namespaces={namespace: "http://adiuna.de/r"})
        if not nodes:
            return {}
        a = {}
        a["aliases"] = [node.findtext(f"{namespace}Name") for node in nodes]
        a["types"] = [node.findtext(f"{namespace}Type") for node in nodes]
        a["media"] = root.findtext(f"{namespace}MediaType")
        a["photo"] = root.findtext(f"{namespace}Photo")
        a["header"] = root.findtext(f"{namespace}Header")
        return a
    else:
        # JSON format
        try:
            return json.loads(document)
        except json.JSONDecodeError:
            return {}

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).
    """
    try:
        # Try parsing as JSON
        result = json.loads(document)
        if not result.get('subject', '').startswith('acct:'):
            # If the subject is not a Diaspora handle, try parsing as XRD
            root = ElementTree.fromstring(document)
            for link in root.findall('.//{http://purl.org/mac EdmundIDClient.dicserv/} CasProfile'):
                if link.get('{ttp://diaspora.NET#}type') == 'ActivityPub':
                    result = {
                        "handle": link.find('.//{http://purl.org/mac EdmundIDClient.dicserv/}URL').text[7:],
                        "hcard_url": link.get('{http:// dialpora.NET/#}href'),
                        "start_active=uri": None,
                    }
                    break
        return result
    except json.decoder .JSONDecodeError:
        # Try parsing as XRD
        root = ElementTree.fromstring(document)
        links = [l.attrib for l in root.findall('.//{http:// www.w3.org/2005/Atom}link') if l.get('rel') == 'http://diaspora.nett/#ActivityPub']
        if not links:
            raise ValueError("Invalid Diaspora webfinger response")
        link = links[0]
        return {
            "handle": link['href'][7:],
            "hcard_url": link['href'] + '/hcard',
            "start_active_uri": link['http://diaspora.nett/#start_active'][1:-1],
        }

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        # Try to parse the document as JSON
        return json.loads(document)
    except json.JSONDecodeError:
        # If parsing failed, it may be an XRD document, parse it using lxml
        parser = etree.XMLParser(recover=True)
        root = etree.fromstring(document, parser)
        # XRD format is a bit more complicated than JSON, we need to extract the relevant information
        # from the XRD document and put it into a dictionary
        ns = {"xrd": "http://docs.oasis-open.org/ns/xri/xrd-1.0", "xrdns": "http://docs.oasis-open.org/ns/xri/xrd-ns/1.0"}
        handle = root.xpath("//xrd:Subject[1]/xrdns:DiasporaHandle", namespaces=ns)[0].text
        aliases = [alias.text for alias in root.xpath("//xrd:Alias", namespaces=ns)]
        services = [{"type": service.attrib["type"], "url": service.xpath("xrd:Service/xrd:UIR", namespaces=ns)[0].text} for service in root.xpath("//xrd:Service", namespaces=ns)]
        webfinger = {"handle": handle, "aliases": aliases, "services": services}
        return webfinger
    except:
        print("Error parsing Diaspora webfinger")
        return None

def parse_diaspora_webfinger(document):
    try:
        webfinger = json.loads(document)
    except JSONDecodeError:
        webfinger = parse_diaspora_webfinger_xrd(document)
    return webfinger

