def dict_insert(dic, val, key, *keys):
    if dic.get(key) is None:
        dic[key] = {}
    if len(keys) == 0:
        dic[key] = val
    else:
        assert len(keys) > 0
        _dict_insert(dic[key], val, *keys)

    return dic

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    try:
        return sorted([
            os.path.join(settings_dirs, fname)
            for fname in os.listdir(settings_dirs)
            if fname.endswith('.ini') or fname == spec_option
        ])
    except OSError:
        return []

def list_of_file_names(settings_dirs, spec_option):
    file_names = []
    for settings_dir in settings_dirs:
        for file_name in os.listdir(settings_dir):
            if file_name.endswith(".ini"):
                file_names.append(os.path.join(settings_dir, file_name))
    if spec_option.lower() == "recursive":
        for file_name in file_names:
            if os.path.isdir(file_name):
                file_names.extend(list_of_file_names(file_name, spec_option))
    return file_names

