def validate_from_content(cls, spec_content=None):
    """validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data
    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    try:
        data = yaml.load(spec_content, Loader=Loader)
    except Exception as e:
        raise IRValidatorException(
            "There was a problem parsing the spec file: {}".format(e))

    errors = []
    for field in ["name", "version", "target_date", "section_count"]:
        if field not in data:
            errors.append(field)

    if errors:
        msg = "Mandatory data missing in spec file: {}".format(", ".join(errors))
        raise IRValidatorException(msg)

    return data

def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    try:
        with yaml_file.open() as f:
            data = yaml.load(f)
        return data
    except IOError as e:
        raise ValidationException('Invalid YAML file: could not open file') from e
    except ValidationError as ve:
        raise ValidationException('Invalid YAML file: error parsing file') from ve
    except KeyError as ke:
        raise ValidationException('Invalid YAML file: missing mandatory data') from ke

def _include_groups(parser_dict):
    """Resolves the include dict directive in the spec files. """
    include_dict = self._extract_spec_include_directive(parser_dict)
    if not include_dict:
        return
    for include_key, include_spec in include_dict.items():
        include_key = include_key.replace(DATA_PREFIX, '')
        include_spec = include_spec.replace(DATA_PREFIX, '')
        include_parser = parser_dict[include_key].get('parser')
        if not include_parser:
            continue
        for include_arg, arg_spec in include_parser.items():
            arg_spec['name'] = include_arg
            arg_spec['group'] = include_key
            arg_spec['help'] = self._format_help(arg_spec['help'])
            self._add_parser_argument(parser, arg_spec)

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    included_dicts = {}
