    for extra_var in extra_vars:
        if not isinstance(extra_var, dict):
            raise ValueError("Extra-vars must be a list of dictionaries")

        for key in extra_var:
            if key not in vars_dict:
                vars_dict[key] = extra_var[key]
            else:
                vars_dict[key] = extra_var[key] + vars_dict[key]

    return vars_dict

def merge_extra_vars(vars_dict, extra_vars=None):
    if extra_vars is None:
        return vars_dict

    for key, value in extra_vars.items():
        if key not in vars_dict:
            vars_dict[key] = value

    return vars_dict

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None, extra_vars=None, ansible_args=None):
    command = ["ansible-playbook", playbook_path]
    if verbose:
        command.append("-vvvvv")
    if extra_vars:
        for k, v in extra_vars.items():
            command.append(f"--extra-vars={k}={v}")
    if ansible_args:
        for k, v in ansible_args.items():
            command.append(f"--{k} {v}")
    p = subprocess.Popen(command, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    if wait:
        stdout, stderr = p.communicate()
        if p.returncode != 0:
            raise RuntimeError(stderr)
    return stdout

def _convert_non_cli_args(parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    arguments_to_convert = ["output_format", "mode", "api_version", "no_confirmation"]
    argument_types = {
        "output_format": "str",
        "mode": "str",
        "api_version": "str",
        "no_confirmation": "bool"
    }
    for argument in arguments_to_convert:
        if argument in values_dict:
            value = values_dict[argument]
            if argument_types[argument] == "bool":
                if value.lower() in ["true", "1"]:
                    values_dict[argument] = True
                elif value.lower() in ["false", "0"]:
                    values_dict[argument] = False
                else:
                    raise ValueError(f"Invalid value for argument: {argument}. Must be a boolean")
            else:
                values_dict[argument] = argument_types[argument](value)
            if argument_types[argument] == "int":
                try:
                    values_dict[argument] = int(values_dict[argument])
                except ValueError:
                    raise ValueError(f"Invalid value for argument: {argument}. Must be an integer")
            if argument_types[argument] == "float":
                try:
                    values_dict[argument] = float(values_dict[argument])
                except ValueError:
                    raise ValueError(f"Invalid value for argument: {argument}. Must be a float")

            return values_dict

