def _convert_non_cli_args(parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    option_types = {
        "main": {
            "--port": int,
            "--host": str,
            "--blotter": str,
            "--nopass": bool,
        },
        "virsh": {
            "--port": int,
            "--host": str,
            "--blotter": str,
            "--nopass": bool,
        },
        "ospd": {
            "--port": int,
            "--host": str,
            "--blotter": str,
            "--nopass": bool,
        },
        "others": {
            "--port": int,
            "--host": str,
            "--blotter": str,
            "--nopass": bool,
        },
    }

    if parser_name not in option_types:
        parser_name = "others"

    for option, value in values_dict.items():
        if option in option_types[parser_name]:
            values_dict[option] = option_types[parser_name][option](value)

    return values_dict

