    return values_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    plugin_spec = {}
    try:
        with open(f"{plugin_dir}/plugin.yml", "r") as f:
            plugin_spec = yaml.safe_load(f.read())
    except FileNotFoundError:
        print(f"Could not find plugin.yml file in {plugin_dir}.")
        return {}

    flatten_dict = {}
    for key, val in plugin_spec.items():
        if isinstance(val, dict):
            for sub_key, sub_val in val.items():
                flatten_dict[f"{key}.{sub_key}"] = sub_val
        else:
            flatten_dict[key] = val

    return flatten_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    plugin_spec = load_yaml_as_dict(plugin_dir / "plugin_spec.yaml")
    fluat_dict = {}
    for k, v in plugin_spec.items():
        if isinstance(v, str):
            fluat_dict[k] = v
        elif isinstance(v, list):
            for item in v:
                if isinstance(item, dict):
                    for key, value in item.items():
                        fluat_dict[key] = value
    return fluat_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    plugin_spec = get_plugin_spec(plugin_dir)
    flatten_dict = {}

    for section in plugin_spec:
        for element in plugin_spec[section]:
            flatten_dict[element] = plugin_spec[section][element]

    return flatten_dict

